/**
 * API Error Utilities
 * Generated by API Builder - do not edit manually
 */

export class ApiException extends Error {
  constructor(
    public readonly response: Response,
    message: string
  ) {
    super(`HTTP ${response.status}: ${message}`);
    this.name = 'ApiException';
  }
}

/**
 * The response arrived and its body is not the JSON the spec declares - a proxy or CDN
 * answering with an HTML error page is the usual cause.
 *
 * Separate from `ApiException` because the status alone says the call succeeded, so a
 * caller that keys off `response.status` would report a 200. `handleApiCall` recognises
 * this by name and reports 502. The parse detail is kept in `message` for a log and never
 * reaches the response envelope, where it would be shown to a person verbatim.
 */
export class ApiParseException extends ApiException {
  constructor(response: Response, message: string) {
    super(response, message);
    this.name = 'ApiParseException';
  }
}

export class Util {
  static async mustParse<T>(response: Response, name: string): Promise<T> {
    try {
      const data = await response.json();
      return data as T;
    } catch (error) {
      throw new ApiParseException(
        response,
        `Unable to parse response body as a ${name}: ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }

  static async mustParseArray<T>(response: Response, name: string): Promise<T[]> {
    try {
      const data = await response.json();
      if (!Array.isArray(data)) {
        throw new ApiParseException(response, `Unable to parse response body. Expected an array but found a ${typeof data}`);
      }
      return data as T[];
    } catch (error) {
      if (error instanceof ApiException) {
        throw error;
      }
      throw new ApiParseException(
        response,
        `Unable to parse response body as a ${name}[]: ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }
}

// ============================================================================
// Client configuration
// ============================================================================

/**
 * Options accepted by every generated `ApiClient` constructor.
 *
 * `headers` are merged into every request the client makes, under any headers the
 * individual call passes. `timeoutMs` aborts the underlying request - the fetch is
 * cancelled, not abandoned - and surfaces as status 504 through `handleApiCall`.
 * `fetch` replaces the global implementation (SvelteKit's per-request `fetch`, a test
 * double).
 */
export interface ApiClientOptions {
  baseUrl: string;
  headers?: Record<string, string>;
  timeoutMs?: number;
  fetch?: typeof fetch;
}

// ============================================================================
// Response envelope
// ============================================================================

/** A single API error, with the form field it belongs to when there is one. */
export interface ApiError {
  message: string;
  field?: string;
}

export interface ApiResponseSuccess<T> {
  data: T;
  /**
   * Always 200, and typed as the literal so the compiler says so.
   *
   * A generated method returns the decoded body and discards the `Response`, so the
   * server's real success code is not available by the time `handleApiCall` builds this -
   * a 201 from a create and a 204 from a delete both arrive here as 200. Branch on `data`,
   * or on the error side of the envelope; `success.status === 201` is a comparison that
   * could never have fired, and this type is what turns it into a compile error instead of
   * a branch that is silently dead.
   */
  status: 200;
}

export interface ApiResponseError {
  errors: ApiError[];
  status: number;
}

/** Every call handled by `handleApiCall` resolves to one of these two. */
export type ApiResponse<T> = ApiResponseSuccess<T> | ApiResponseError;

export function isApiError<T>(response: ApiResponse<T>): response is ApiResponseError {
  return 'errors' in response;
}

export function isApiSuccess<T>(response: ApiResponse<T>): response is ApiResponseSuccess<T> {
  return 'data' in response;
}

export interface ApiCallOptions {
  /** Called before the error is returned, when the server answered 401. */
  onUnauthorized?: () => void;
  /**
   * Called for every failure that carries a status - the server's own non-2xx answers,
   * and the 502 an unreadable success body is reported as. Never for a network failure
   * or a timeout, where there is no response to report.
   */
  onError?: (info: { status: number; url: string; errors: ApiError[] }) => void;
}

const NETWORK_ERROR_MESSAGE = 'Unable to connect to the server. Please check your internet connection and try again.';

const TIMEOUT_ERROR_MESSAGE = 'Request timed out. Please try again.';

const UNREADABLE_RESPONSE_MESSAGE = 'The server sent a response we could not read. Please try again.';

/**
 * The message shown when the server answered with a status and no usable body.
 * One table, so the same backend answer does not read differently in two apps.
 */
export function statusMessage(status: number): string {
  switch (status) {
    case 400:
      return 'Invalid request';
    case 401:
      return 'Unauthorized';
    case 403:
      return 'Forbidden';
    case 404:
      return 'Not found';
    case 409:
      return 'Conflict';
    case 429:
      return 'Too many requests. Please try again shortly.';
    default:
      return status >= 500 ? 'The server encountered an error. Please try again.' : `Request failed (${status})`;
  }
}

function isResponseCarrier(error: unknown): error is { response: Response } {
  if (typeof error !== 'object' || error === null || !('response' in error)) {
    return false;
  }
  const response = (error as { response: unknown }).response;
  return typeof response === 'object' && response !== null && typeof (response as { status?: unknown }).status === 'number';
}

function toApiError(value: unknown): ApiError | undefined {
  if (typeof value === 'string') {
    return { message: value };
  }
  if (typeof value !== 'object' || value === null) {
    return undefined;
  }
  const record = value as { message?: unknown; field?: unknown };
  if (typeof record.message !== 'string') {
    return undefined;
  }
  return typeof record.field === 'string' ? { message: record.message, field: record.field } : { message: record.message };
}

function decodeErrors(body: unknown, status: number): ApiError[] {
  if (Array.isArray(body)) {
    const errors = body.map(toApiError).filter((e): e is ApiError => e !== undefined);
    if (errors.length > 0) {
      return errors;
    }
  } else if (typeof body === 'object' && body !== null) {
    const nested = (body as { errors?: unknown }).errors;
    if (Array.isArray(nested)) {
      const errors = nested.map(toApiError).filter((e): e is ApiError => e !== undefined);
      if (errors.length > 0) {
        return errors;
      }
    }
    const single = toApiError(body);
    if (single !== undefined) {
      return [single];
    }
  }
  return [{ message: statusMessage(status) }];
}

async function readJsonBody(response: Response): Promise<unknown> {
  try {
    const text = await response.text();
    if (text.trim() === '') {
      return undefined;
    }
    return JSON.parse(text) as unknown;
  } catch {
    return undefined;
  }
}

function isAbort(error: unknown): boolean {
  return error instanceof Error && (error.name === 'AbortError' || error.name === 'TimeoutError');
}

/**
 * A success whose body could not be decoded, thrown by `Util.mustParse`. Recognised by
 * name rather than by `instanceof`: a consumer can hold two copies of this module (an
 * app and its test harness), and a nominal check fails across them.
 */
function isParseFailure(error: unknown): error is { response: Response } {
  return error instanceof Error && error.name === 'ApiParseException' && isResponseCarrier(error);
}

function networkMessage(error: unknown): string {
  if (!(error instanceof Error)) {
    return NETWORK_ERROR_MESSAGE;
  }
  const message = error.message.toLowerCase();
  if (message.includes('timeout')) {
    return TIMEOUT_ERROR_MESSAGE;
  }
  if (message.includes('fetch failed') || message.includes('failed to fetch') || message.includes('network')) {
    return NETWORK_ERROR_MESSAGE;
  }
  // Anything else - a `SyntaxError` from a body that is not JSON, a bug in the client -
  // is a message written for a developer. The envelope is read by a person, so it says
  // the one true thing instead: the request did not complete.
  return NETWORK_ERROR_MESSAGE;
}

/**
 * Run a generated client call and convert whatever it throws into an `ApiResponse`.
 *
 * The generated clients signal every non-success status by throwing, so the four
 * outcomes a caller has to tell apart - data, field errors, a status with no body,
 * and the server not answering at all - are collapsed here into one discriminated
 * union. Status 0 means the request never reached the server; 504 means it was
 * cancelled by a timeout; 502 means it arrived and the body could not be decoded.
 *
 * Those three, and every status on the error side, are real. The SUCCESS side is always
 * 200 - see `ApiResponseSuccess.status` - because the generated methods hand back a
 * decoded body rather than a `Response`.
 *
 * This consumes the error response's body. Do not also call the thrown wrapper's
 * own accessor (`validationErrors()`, `unauthorizedError()`) on the same error - a
 * `Response` body can only be read once.
 *
 * @example
 * const result = await handleApiCall(() => client.getUsers({ headers }));
 * if (isApiError(result)) {
 *   // result.errors: field-specific when the server sent them
 * }
 */
export async function handleApiCall<T>(apiCall: () => Promise<T>, options?: ApiCallOptions): Promise<ApiResponse<T>> {
  try {
    const data = await apiCall();
    // 200 for every success, whatever the server sent: `apiCall` resolves to the decoded
    // body and the `Response` it came from is already gone. `ApiResponseSuccess.status`
    // is typed `200` so a caller cannot write a 2xx test that never fires.
    return { status: 200, data };
  } catch (error) {
    if (isParseFailure(error)) {
      // The gateway answered with a success status and a body that is not the JSON the
      // spec declares - typically an HTML error page. Reported as 502 rather than as the
      // status the gateway sent, which would read as a success, and rather than as 0,
      // which means the request never arrived. The parse detail stays on the thrown
      // `ApiParseException` for a log; it is never phrased for a person.
      const errors = [{ message: UNREADABLE_RESPONSE_MESSAGE }];
      if (options?.onError) {
        options.onError({ status: 502, url: error.response.url, errors });
      }
      return { status: 502, errors };
    }
    if (isResponseCarrier(error)) {
      const response = error.response;
      const status = response.status;
      if (status >= 200 && status < 300) {
        // A success the client models as a throw (a `void` response declared as an
        // error type). There is no body to decode and nothing failed. Reported as 200
        // like every other success rather than as the status this one happens to carry:
        // the envelope has one success shape, and a caller that could read a real 204
        // here and only here would be reading it by accident.
        return { status: 200, data: undefined as T };
      }
      const errors = decodeErrors(await readJsonBody(response), status);
      if (status === 401 && options?.onUnauthorized) {
        options.onUnauthorized();
      }
      if (options?.onError) {
        options.onError({ status, url: response.url, errors });
      }
      return { status, errors };
    }
    if (isAbort(error)) {
      return { status: 504, errors: [{ message: TIMEOUT_ERROR_MESSAGE }] };
    }
    return { status: 0, errors: [{ message: networkMessage(error) }] };
  }
}

/**
 * Bound a call that cannot be given a signal. Prefer `new ApiClient({ baseUrl,
 * timeoutMs })`, which aborts the request itself; this races a timer instead and
 * ABANDONS the in-flight request, so the server finishes the work regardless.
 */
export async function handleApiCallWithTimeout<T>(
  apiCall: () => Promise<T>,
  timeoutMs: number,
  options?: ApiCallOptions
): Promise<ApiResponse<T>> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<ApiResponse<T>>((resolve) => {
    timer = setTimeout(() => resolve({ status: 504, errors: [{ message: TIMEOUT_ERROR_MESSAGE }] }), timeoutMs);
  });
  try {
    return await Promise.race([handleApiCall(apiCall, options), timeout]);
  } finally {
    clearTimeout(timer);
  }
}

// ============================================================================
// Request headers
// ============================================================================

export interface RequestHeaderOptions {
  /** True in production, where no bypass header is ever sent. */
  isProduction: boolean;
  /**
   * Further headers sent only off production, beside `X-Bypass-Rate-Limit` - an app
   * whose Playwright runs also trip the dev-only N+1 detector passes
   * `{ 'X-Bypass-N1-Detection': 'true' }`.
   */
  extraBypassHeaders?: Record<string, string>;
}

/** The headers that exempt a request from rate limiting off production, and nothing in production. */
export function rateLimitBypassHeaders(options: RequestHeaderOptions): Record<string, string> {
  if (options.isProduction) {
    return {};
  }
  return { 'X-Bypass-Rate-Limit': 'true', ...options.extraBypassHeaders };
}

/** The headers that authenticate a call as the signed-in user, plus the bypass headers. */
export function sessionHeaders(sessionId: string | undefined, options: RequestHeaderOptions): Record<string, string> {
  const bypass = rateLimitBypassHeaders(options);
  if (!sessionId) {
    return bypass;
  }
  return { ...bypass, session_id: sessionId };
}
